// Given distinct candidate rows and CURRENT blue sevens, test six-site probes derived BEFORE deletion. Necessity only: a legal eight must contain six compatible hits with >=2 common extensions. Never choose an eighth row.
use std::io::{self,Read};type B=Vec<u64>;
fn search(adj:&[B],mut opt:B,free:&B,k:u32,extra:u32)->bool{if free.iter().map(|x|x.count_ones()).sum::<u32>()<k+extra{return false}if k==0{return true}let mut n=opt.iter().map(|x|x.count_ones()).sum::<u32>();for w in 0..opt.len(){while opt[w]!=0{if n<k{return false}let i=64*w+opt[w].trailing_zeros()as usize;opt[w]&=opt[w]-1;n-=1;let p=opt.iter().zip(&adj[i]).map(|(a,b)|a&b).collect();let f=free.iter().zip(&adj[i]).map(|(a,b)|a&b).collect();if search(adj,p,&f,k-1,extra){return true}}}false}
fn main(){let mut st=String::new();io::stdin().read_to_string(&mut st).unwrap();let mut it=st.lines().map(|l|l.split_whitespace().map(|v|v.parse::<u32>().unwrap()).collect::<Vec<_>>());let rows=it.next().unwrap();let old=it.next().unwrap();let tests=it.next().unwrap();let n=rows.len();let w=(n+63)/64;let mut f=vec![u64::MAX;w];if n%64!=0{f[w-1]=(1<<(n%64))-1}let mut adj=vec![f.clone();n];for q in old{let mut miss=vec![0;w];let ids:Vec<_>=(0..n).filter(|&i|rows[i]&q==0).collect();for &i in &ids{miss[i/64]|=1<<(i%64)}for i in ids{for j in 0..w{adj[i][j]&=!miss[j]}}}for i in 0..n{adj[i][i/64]&=!(1<<(i%64))}
for q in tests{let mut hits=vec![0u64;w];for(i,&s)in rows.iter().enumerate(){if s&q!=0{hits[i/64]|=1<<(i%64)}}let pass=search(&adj,hits.clone(),&f,6,2);let hits_only=pass||search(&adj,hits,&f,6,0);println!("{} {} {}",q,hits_only as u8,pass as u8)}}
